def pluralize(word):
    endings = ('s', 'x', 'z', 'ch', 'sh')
    if any(word.endswith(e) for e in endings):
        return word + 'es'
    if len(word) > 1 and word[-1] == 'y' and word[-2] not in 'aeiou':
        return word[:-1] + 'ies'
    return word + 's'

