def count_divisors_of_factorial(n):
    if n <= 1:
        return 1
    is_composite = [False] * (n + 1)
    primes = []
    for p in range(2, n + 1):
        if not is_composite[p]:
            primes.append(p)
            for multiple in range(p * p, n + 1, p):
                is_composite[multiple] = True
    result = 1
    for p in primes:
        exponent = 0
        power = p
        while power <= n:
            exponent += n // power
            power *= p
        result *= (exponent + 1)
    return result

