def smallest_number_with_digit_sum(s, d):
    if d <= 0 or s < 1 or s > 9 * d:
        return -1
    digits = []
    remaining_sum = s
    for pos in range(d):
        remaining_positions = d - pos - 1
        min_digit = 1 if pos == 0 else 0
        for digit in range(min_digit, 10):
            if 0 <= remaining_sum - digit <= 9 * remaining_positions:
                digits.append(digit)
                remaining_sum -= digit
                break
    return int(''.join(map(str, digits)))

