def primes_up_to(n):
    result = []
    for candidate in range(2, n + 1):
        is_prime = True
        for d in range(2, int(candidate ** 0.5) + 1):
            if candidate % d == 0:
                is_prime = False
                break
        if is_prime:
            result.append(candidate)
    return result

