def is_valid_isbn10(s):
    cleaned = s.replace("-", "")
    if len(cleaned) != 10:
        return False
    if not cleaned[:9].isdigit():
        return False
    if cleaned[9] != "X" and not cleaned[9].isdigit():
        return False
    total = 0
    for ch, w in zip(cleaned, range(10, 0, -1)):
        total += (10 if ch == "X" else int(ch)) * w
    return total % 11 == 0

